labs.solution_sql:
CREATE OR REPLACE DATABASE SB_LAB_DB;
CREATE OR REPLACE SCHEMA SB_LAB_DB.CORE;

CREATE OR REPLACE FILE FORMAT SB_LAB_DB.CORE.CSV_FF
  TYPE = CSV
  SKIP_HEADER = 1
  FIELD_OPTIONALLY_ENCLOSED_BY = '"';

CREATE OR REPLACE STAGE SB_LAB_DB.CORE.ORDERS_STAGE
  FILE_FORMAT = SB_LAB_DB.CORE.CSV_FF;

CREATE OR REPLACE TABLE SB_LAB_DB.CORE.ORDERS (
  ORDER_ID NUMBER,
  CUSTOMER_ID NUMBER,
  AMOUNT NUMBER(10,2)
);

COPY INTO SB_LAB_DB.CORE.ORDERS
FROM @SB_LAB_DB.CORE.ORDERS_STAGE;

CREATE ROLE IF NOT EXISTS AR_SNOWPRO_CORE_READ;
CREATE ROLE IF NOT EXISTS FR_SNOWPRO_ANALYST;

GRANT USAGE ON WAREHOUSE SB_LAB_WH TO ROLE AR_SNOWPRO_CORE_READ;
GRANT USAGE ON DATABASE SB_LAB_DB TO ROLE AR_SNOWPRO_CORE_READ;
GRANT USAGE ON SCHEMA SB_LAB_DB.CORE TO ROLE AR_SNOWPRO_CORE_READ;
GRANT SELECT ON ALL TABLES IN SCHEMA SB_LAB_DB.CORE TO ROLE AR_SNOWPRO_CORE_READ;
GRANT SELECT ON FUTURE TABLES IN SCHEMA SB_LAB_DB.CORE TO ROLE AR_SNOWPRO_CORE_READ;

GRANT ROLE AR_SNOWPRO_CORE_READ TO ROLE FR_SNOWPRO_ANALYST;
SHOW GRANTS TO ROLE AR_SNOWPRO_CORE_READ;

CREATE OR REPLACE DATABASE SB_LAB_DB_CLONE CLONE SB_LAB_DB;

SELECT COUNT(*)
FROM SB_LAB_DB.CORE.ORDERS
AT (OFFSET => -60 * 5);

DROP TABLE SB_LAB_DB_CLONE.CORE.ORDERS;
UNDROP TABLE SB_LAB_DB_CLONE.CORE.ORDERS;

SELECT DATABASE_NAME, RETENTION_TIME
FROM SNOWFLAKE.ACCOUNT_USAGE.DATABASES
WHERE DATABASE_NAME IN ('SB_LAB_DB', 'SB_LAB_DB_CLONE');

CREATE OR REPLACE TABLE RAW_ORDERS (ORDER_ID NUMBER, AMOUNT NUMBER(10,2));
CREATE OR REPLACE TABLE ORDER_FACTS (ORDER_ID NUMBER, AMOUNT NUMBER(10,2), PROCESSED_AT TIMESTAMP_NTZ);

CREATE OR REPLACE STREAM RAW_ORDERS_STREAM ON TABLE RAW_ORDERS;

CREATE OR REPLACE TASK LOAD_ORDER_FACTS
  WAREHOUSE = SB_LAB_WH
  SCHEDULE = '5 MINUTE'
  WHEN SYSTEM$STREAM_HAS_DATA('RAW_ORDERS_STREAM')
AS
INSERT INTO ORDER_FACTS
SELECT ORDER_ID, AMOUNT, CURRENT_TIMESTAMP()
FROM RAW_ORDERS_STREAM
WHERE METADATA$ACTION = 'INSERT';

INSERT INTO RAW_ORDERS VALUES (1, 10.00), (2, 25.50);
EXECUTE TASK LOAD_ORDER_FACTS;
SELECT * FROM ORDER_FACTS;

labs.teardown_sql:
DROP TASK IF EXISTS LOAD_ORDER_FACTS;
DROP STREAM IF EXISTS RAW_ORDERS_STREAM;
DROP TABLE IF EXISTS ORDER_FACTS;
DROP TABLE IF EXISTS RAW_ORDERS;

