CREATE OR REPLACE DATABASE SB_ARCH_DB;
CREATE OR REPLACE ROLE SB_AR_READ;
CREATE OR REPLACE SCHEMA SB_ARCH_DB.SB_GOV WITH MANAGED ACCESS;
GRANT USAGE ON DATABASE SB_ARCH_DB TO ROLE SB_AR_READ;
GRANT USAGE ON SCHEMA SB_ARCH_DB.SB_GOV TO ROLE SB_AR_READ;
GRANT SELECT ON FUTURE TABLES IN SCHEMA SB_ARCH_DB.SB_GOV TO ROLE SB_AR_READ;

CREATE OR REPLACE TAG SB_SENSITIVITY;
CREATE OR REPLACE MASKING POLICY SB_EMAIL_MASK AS (val STRING) RETURNS STRING -> CASE WHEN IS_ROLE_IN_SESSION('SB_PRIVILEGED') THEN val ELSE '***MASKED***' END;
ALTER TABLE SB_CUSTOMERS MODIFY COLUMN EMAIL SET MASKING POLICY SB_EMAIL_MASK;

