SHOW REPLICATION DATABASES;

CREATE OR REPLACE FILE FORMAT SB_CSV_FF TYPE = CSV SKIP_HEADER = 1;
CREATE OR REPLACE STAGE SB_EXT_STAGE URL = 's3://example-bucket/path/' FILE_FORMAT = SB_CSV_FF;
CREATE OR REPLACE PIPE SB_LOAD_PIPE AUTO_INGEST = TRUE AS COPY INTO SB_RAW FROM @SB_EXT_STAGE FILE_FORMAT = SB_CSV_FF;

CREATE OR REPLACE FUNCTION SB_NORMALIZE_EMAIL(email STRING) RETURNS STRING LANGUAGE PYTHON RUNTIME_VERSION = '3.11' HANDLER = 'normalize' AS $$
def normalize(email):
    return email.strip().lower() if email else None
$$;
